<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Choose password - <?php echo htmlspecialchars(SITENAME); ?></title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;display:grid;place-items:center;min-height:100vh;margin:0}.card{background:#fff;padding:32px;border-radius:16px;max-width:440px;width:calc(100% - 48px)}input,button{box-sizing:border-box;width:100%;padding:12px;margin-top:10px}button{background:#0f766e;color:#fff;border:0}.error{color:#b91c1c}</style></head><body><main class="card"><h1>Choose a new password</h1><?php if ($error): ?><p class="error"><?php echo htmlspecialchars($error); ?></p><?php endif; ?><?php if ($reset): ?><p>Use at least <?php echo PASSWORD_MIN_LENGTH; ?> characters.</p><form method="post"><?php echo csrfInput(); ?><input type="password" name="password" minlength="<?php echo PASSWORD_MIN_LENGTH; ?>" autocomplete="new-password" required><input type="password" name="confirm_password" minlength="<?php echo PASSWORD_MIN_LENGTH; ?>" autocomplete="new-password" required><button type="submit">Reset password</button></form><?php endif; ?></main></body></html>
